__global__ void matmul_kernel(const nv_bfloat16* A,const nv_bfloat16* B,nv_bfloat16* C,
                              int M,int N,int K){
    constexpr int MMA_K=16;
    constexpr int WARP_M=BLOCK_M/NUM_WARP_M;
    constexpr int WARP_N=BLOCK_N/NUM_WARP_N;
    constexpr int TB_SIZE=NUM_WARP_M*NUM_WARP_N*WARP_SIZE;
    constexpr int NUM_MMA_M=WARP_M/MMA_M;
    constexpr int NUM_MMA_N=WARP_N/MMA_N;

    int tid=threadIdx.x;
    int bid=blockIdx.x;
    int warp_id=tid/WARP_SIZE;
    int lane_id=tid%WARP_SIZE;

    int num_blocks_n=cdiv(N,BLOCK_N);
    int bid_m=bid/num_blocks_n;
    int bid_n=bid%num_blocks_n;

    int offset_m=bid_m*BLOCK_M;
    int offset_n=bid_n*BLOCK_N;

    int warp_id_m=warp_id/NUM_WARP_N;
    int warp_id_n=warp_id%NUM_WARP_N;

    A += offset_m*K;
    B += offset_n*K;
    C += (offset_m+warp_id_m*WARP_M)*N + (offset_n+warp_id_n*WARP_N);

    extern __shared__ nv_bfloat16 shm[];
    nv_bfloat16* As=shm;
    nv_bfloat16* Bs=As+(BLOCK_M*SHM_STRIDE);

    constexpr int num_acc_regs=MMA_M*MMA_N/WARP_SIZE;
    constexpr int num_A_regs=MMA_M*MMA_K*sizeof(nv_bfloat16)/4/WARP_SIZE;
    constexpr int num_B_regs=MMA_N*MMA_K*sizeof(nv_bfloat16)/4/WARP_SIZE;

    float acc[NUM_MMA_M][NUM_MMA_N][num_acc_regs] = {};

    for(int block_k=0; block_k<K; block_k+=BLOCK_K){
        global_to_shared_async<TB_SIZE,BLOCK_M,BLOCK_K,SHM_STRIDE>(A,K,As,tid);
        global_to_shared_async<TB_SIZE,BLOCK_N,BLOCK_K,SHM_STRIDE>(B,K,Bs,tid);
        cp_async_wait_all();
        __syncthreads();

        #pragma unroll
        for(int k=0;k<BLOCK_K;k+=MMA_K){
            const nv_bfloat16* Awarp=As+(warp_id_m*WARP_M)*SHM_STRIDE+k;
            const nv_bfloat16* Bwarp=Bs+(warp_id_n*WARP_N)*SHM_STRIDE+k;

            uint32_t Breg[NUM_MMA_N][num_B_regs];

            #pragma unroll
            for(int n=0;n<NUM_MMA_N;n++){
                const nv_bfloat16* Bptr =
                    Bwarp+(n*MMA_N+(lane_id%8))*SHM_STRIDE+(lane_id/8)*8;
                ldmatrix_x2(Breg[n], cvta_shared(Bptr));
            }

            #pragma unroll
            for(int m=0;m<NUM_MMA_M;m++){
                uint32_t Areg[num_A_regs];
                const nv_bfloat16* Aptr =
                    Awarp+(m*MMA_M+(lane_id%16))*SHM_STRIDE+(lane_id/16)*8;
                ldmatrix_x4(Areg, cvta_shared(Aptr));

                #pragma unroll
                for(int n=0;n<NUM_MMA_N;n++){
                    mma_m16n8k16(Areg,Breg[n],acc[m][n]);
                }
            }
        }

        __syncthreads();
        A+=BLOCK_K;
        B+=BLOCK_K;
    }

    #pragma unroll
    for(int m=0;m<NUM_MMA_M;m++) {
        #pragma unroll
        for(int n=0;n<NUM_MMA_N;n++){
